const alert = $json.body;

let severity = "unknown";
const ruleLevel = alert.rule ? alert.rule.level : 0;

if (ruleLevel >= 10) {
  severity = "critical";
} else if (ruleLevel >= 7) {
  severity = "high";
} else if (ruleLevel >= 5) {
  severity = "medium";
} else if (ruleLevel >= 3) {
  severity = "low";
}

return [{
  json: {
    alertId: alert.id,
    timestamp: alert.timestamp,
    ruleId: alert.rule ? alert.rule.id : null,
    ruleDescription: alert.rule ? alert.rule.description : null,
    ruleLevel: ruleLevel,
    agentName: alert.agent ? alert.agent.name : null,
    agentId: alert.agent ? alert.agent.id : null,
    srcIp: alert.data ? alert.data.srcip : null,
    dstIp: alert.data ? alert.data.dstip : null,
    protocol: alert.data ? alert.data.protocol : null,
    fullAlert: alert,
    severity: severity
  }
}];

